def listar_arquivos_auditados(raiz: Path) -> list[str]:
    if not raiz.is_dir():
        return []

    return sorted(
                        pasta.name
                        for pasta in raiz.iterdir()
                        if pasta.is_dir()
                        and (pasta / "MANIFESTOS" / "indice.json").is_file()
                    )

def carregar_indice(raiz: Path, id_arquivo: str) -> dict:
